def encode(message):
    def transform_char(c):
        if c.isalpha():
            if c.lower() in 'aeiou':
                # Find the letter 2 places ahead in the alphabet
                new_char = chr(((ord(c.lower()) - ord('a') + 2) % 26) + ord('a'))
                # Swap case
                return new_char.upper() if c.isupper() else new_char.lower()
            else:
                # Swap case
                return c.upper() if c.islower() else c.lower()
        return c

    return ''.join(transform_char(c) for c in message)
