def is_samepatterns(seq, patterns):
    if len(seq) != len(patterns):
        return False

    pattern_map = {}
    used_patterns = set()

    for s, p in zip(seq, patterns):
        if p in pattern_map:
            if pattern_map[p] != s:
                return False
        else:
            if s in used_patterns:
                return False
            pattern_map[p] = s
            used_patterns.add(s)

