def magic_square_test(matrix):
    n = len(matrix)
    if n == 0:
        return False

    # Calculate the sum of the first row to use as the magic constant
    magic_sum = sum(matrix[0])

    # Check sums of all rows
    for row in matrix:
        if sum(row) != magic_sum:
            return False

    # Check sums of all columns
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != magic_sum:
            return False

    # Check sum of the main diagonal
    if sum(matrix[i][i] for i in range(n)) != magic_sum:
        return False

    # Check sum of the secondary diagonal
    if sum(matrix[i][n - 1 - i] for i in range(n)) != magic_sum:
        return False

    return True
