def max_sub_array_sum_repeated(arr, n, k):
    def kadane(arr):
        max_ending_here = max_so_far = arr[0]
        for x in arr[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    if k == 1:
        return kadane(arr)

    total_sum = sum(arr)
    max_kadane = kadane(arr)
    max_wrap = 0

    for i in range(n):
        max_wrap += arr[i]
        arr[i] = -arr[i]
    max_wrap += kadane(arr)

    if total_sum > 0:
        return max_kadane + (k - 2) * total_sum + max_wrap
    else:
        return max(max_kadane, max_wrap)
