def max_sum_increasing_subseq(arr, n, i, k):
    # Initialize dp array where dp[j] will store the maximum sum of increasing subsequence
    # ending at index j
    dp = [0] * n
    for j in range(n):
        dp[j] = arr[j]

    # Compute maximum sum of increasing subsequence for each index
    for j in range(1, n):
        for l in range(j):
            if arr[j] > arr[l]:
                dp[j] = max(dp[j], dp[l] + arr[j])

    # Find the maximum sum of increasing subsequence from prefix until ith index
    max_sum_until_i = 0
    for j in range(i + 1):
        max_sum_until_i = max(max_sum_until_i, dp[j])

    # Check if we can include the kth element in the subsequence
    if arr[k] > arr[i]:
        return max_sum_until_i + arr[k]
    else:
        return max_sum_until_i
