def rearrange_bigger(n):
    digits = list(str(n))
    length = len(digits)

    # Step 1: Find the rightmost digit that is smaller than the digit next to it
    for i in range(length - 2, -1, -1):
        if digits[i] < digits[i + 1]:
            # Step 2: Find the smallest digit on the right side of (i-th digit) which is larger than digits[i]
            for j in range(length - 1, i, -1):
                if digits[j] > digits[i]:
                    # Step 3: Swap the found digits
                    digits[i], digits[j] = digits[j], digits[i]
                    # Step 4: Reverse the digits after the (i-th) position
                    digits[i + 1:] = reversed(digits[i + 1:])
                    return int(''.join(digits))
    return False
