        return 3
    elif n == 1:
        return 3 + 0
    elif n == 2:
        return 3 + 0 + 2

    p0, p1, p2 = 3, 0, 2
    total_sum = p0 + p1 + p2

    for i in range(3, n + 1):
        pn = p0 + p1
        total_sum += pn
        p0, p1, p2 = p1, p2, pn

