def max_product(nums):
    n = len(nums)
    if n == 0:
        return 0

    # dp[i] will store the maximum product of an increasing subsequence ending with nums[i]
    dp = nums[:]

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] * nums[i])

    return max(dp)
```

