```python
def min_Swaps(a, b):
    if len(a) != len(b):
        return "Not Possible"

    count_a = a.count('1')
    count_b = b.count('1')

    if count_a != count_b:
        return "Not Possible"

    swaps = 0
    i, j = 0, len(a) - 1

    while i < j:
        if a[i] != b[i]:
            if a[j] == b[j]:
                swaps += 1
                a = a[:i] + a[j] + a[i+1:j] + a[i] + a[j+1:]
            else:
                swaps += 1
                a = a[:j] + a[i] + a[j+1:]
                i += 1
        i += 1
        j -= 1

    return swaps
```

