def find_kth(arr1, arr2, k):
    def kth_element(i, j, k):
        if i >= len(arr1):
            return arr2[j + k - 1]
        if j >= len(arr2):
            return arr1[i + k - 1]
        if k == 1:
            return min(arr1[i], arr2[j])

        mid1 = float('inf') if i + k // 2 - 1 >= len(arr1) else arr1[i + k // 2 - 1]
        mid2 = float('inf') if j + k // 2 - 1 >= len(arr2) else arr2[j + k // 2 - 1]

        if mid1 < mid2:
            return kth_element(i + k // 2, j, k - k // 2)
        else:
            return kth_element(i, j + k // 2, k - k // 2)

    return kth_element(0, 0, k)
```

