def get_median(list1, list2, n):
    if n == 1:
        return (list1[0] + list2[0]) / 2

    m1 = get_median(list1[:n//2], list2[:n//2], n//2)
    m2 = get_median(list1[n//2:], list2[n//2:], n//2)

    if n % 2 == 0:
        return (max(m1, list1[n//2 - 1]) + min(m2, list2[n//2])) / 2
    else:
        return max(m1, list1[n//2 - 1])
