def pack_consecutive_duplicates(lst):
    if not lst:
        return []

    packed = []
    current = [lst[0]]

    for item in lst[1:]:
        if item == current[-1]:
            current.append(item)
        else:
            packed.append(current)
            current = [item]

    packed.append(current)
    return packed
```

